python3 -c "
import json
with open('/app/resources/treasury_bulletin_1990_09.json', 'r') as f:
    data = json.load(f)
doc = data['document']
elements = doc['elements']

# Get all text content for Exhibits 1, 2, and 3 to see more details
exhibits = {}
current_exhibit = None

for el in elements:
    if el.get('type') == 'section_header':
        content = el.get('content', '')
        if 'Exhibit' in content:
            current_exhibit = content
            if current_exhibit not in exhibits:
                exhibits[current_exhibit] = []
    elif current_exhibit and el.get('type') == 'text':
        exhibits[current_exhibit].append(el.get('content'))

for exhibit, texts in exhibits.items():
    print(f'=== {exhibit} ===')
    for text in texts:
        print(text)
    print()
"
